"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["77519"],{4409(a){a.exports=JSON.parse('{"registro":{"codigo":"uniplus.selecao.configuracao_distribuicao_vagas.modalidade_duplicada","status":422,"titulo":"Cada modalidade s\xf3 pode ser selecionada uma vez por oferta"},"descricao":{"codigo":"uniplus.selecao.configuracao_distribuicao_vagas.modalidade_duplicada","requisitos":["UNI-REQ-0134"],"oQueAconteceu":["Duas ou mais entradas de `modalidadeIds`, na mesma distribui\xe7\xe3o de vagas,\\nresolveram para o mesmo c\xf3digo de modalidade. Cada modalidade participa de\\numa oferta no m\xe1ximo uma vez.","Esta confer\xeancia s\xf3 roda **depois** que os Ids informados s\xe3o resolvidos contra\\no cat\xe1logo de modalidades (por isso n\xe3o acumula com\\n[`vagas_ofertadas_base_invalido`](/erros/uniplus.selecao.configuracao_distribuicao_vagas.vagas_ofertadas_base_invalido),\\n[`percentual_da_reserva_legal_fora_do_limite`](/erros/uniplus.selecao.configuracao_distribuicao_vagas.percentual_da_reserva_legal_fora_do_limite)\\ne\\n[`modalidades_vazias`](/erros/uniplus.selecao.configuracao_distribuicao_vagas.modalidades_vazias)\\n\u2014 essas tr\xeas s\xf3 liberam a passagem para esta consulta quando v\xeam limpas para\\n**todas** as distribui\xe7\xf5es do corpo do pedido, ent\xe3o nunca aparecem na mesma resposta\\nque esta). A partir daqui, o processamento \xe9 por distribui\xe7\xe3o: a primeira\\ndistribui\xe7\xe3o do corpo do pedido cuja resolu\xe7\xe3o falhar interrompe a passada \u2014 as\\ndistribui\xe7\xf5es seguintes do mesmo corpo do pedido n\xe3o chegam a ser conferidas.","Dentro de uma distribui\xe7\xe3o, por\xe9m, esta confer\xeancia **acumula** com outras\\nviola\xe7\xf5es de coer\xeancia do conjunto de modalidades j\xe1 resolvido (por exemplo,\\numa refer\xeancia cruzada de composi\xe7\xe3o/remanejamento apontando para um c\xf3digo\\nfora da oferta) \u2014 todas no mesmo array `errors[]`, sob o campo\\n`distribuicaoVagas[<\xedndice>].modalidadeIds`."],"comoResolver":["Revise a lista `modalidadeIds` da distribui\xe7\xe3o indicada e garanta que cada\\nmodalidade apare\xe7a no m\xe1ximo uma vez."],"ondeAparece":["Defini\xe7\xe3o de distribui\xe7\xe3o de vagas do processo seletivo"]},"modulo":{"id":"selecao","nome":"Sele\xe7\xe3o","assunto":"Configuracao distribuicao vagas"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"0258f07cac6c9b7f9d70290a4b0385549eb99572"}}')}}]);